      "heroSummary": "神奇峡湾Pātea由主峡湾与多条深入群山的支峡构成，至霍尔支峡尽头的水域长度约40公里。与公路直达的米尔福德不同，这里必须经马纳波里湖船运和威尔莫特山口接驳进入。原始温带雨林、海洋水域与降雨形成的低盐度表层共同塑造独特生态环境。资料依据为DOC Doubtful Sound/Patea Area、RealNZ过夜巡游说明、Mapcarta及公开海洋研究地理资料。船上机位坐标为对应湾区或岛屿的代表性定位，并非固定航迹；偏远支峡须选择明确覆盖该区域的多日船或定制航线。",
