      "heroSummary": "蒂阿瑙拥有峡湾国家公园东侧较为开阔的冰川湖泊与完整的高山生态垂直分带。湖西岸石灰岩地下暗河隐藏着新西兰特有发光昆虫，开普勒步道则从山毛榉森林攀升至海拔千米以上的高山草甸和裸露山脊，可俯瞰蒂阿瑙湖南峡及马纳波里湖方向的山地景观。资料依据为DOC Kepler Track、DOC露营地和山屋资料、RealNZ Glowworm Caves、Mapcarta以及公开Kepler步道地图坐标。双湖全景取决于机位、地形与能见度，并非所有山脊均可同时看清两湖。",
