      "heroSummary": "瓦纳卡以冰川雕刻出的深蓝湖泊、金黄色高山草甸和南阿尔卑斯雪峰构成新西兰南岛最具层次感的山水景观。湖畔孤独柳树在清晨薄雾中呈现东方水墨意境，罗伊峰与伊斯特莫斯峰将冰川湖湾展开为壮阔的立体地形画卷，向北沿SH6又可深入哈威亚湖和布鲁斯池的冰川蓝色世界。主要路线依据新西兰自然保护部DOC及瓦纳卡官方旅游资料核对，坐标采用公开地理数据，个别摄影点为景观代表位置而非实地测量的脚架位置。",
